package kr.workbench;
import java.nio.file.*;import java.util.*;import java.nio.charset.StandardCharsets;
public final class JsMinerTest {
 static int count;static void ok(String n,boolean b){if(!b)throw new AssertionError(n);count++;System.out.println("PASS "+n);}
 static void bad(String n,Runnable r){boolean b=false;try{r.run();}catch(Exception e){b=true;}ok(n,b);}
 public static void main(String[] args)throws Exception{
  String map="{\"version\":3,\"sources\":[\"../../escape.js\"],\"sourcesContent\":[\"fetch('/api/recovered',{method:'POST'});\"],\"names\":[],\"mappings\":\"\"}";
  String inline="fetch('/public');\n//# sourceMappingURL=data:application/json;base64,"+Base64.getEncoder().encodeToString(map.getBytes(StandardCharsets.UTF_8));
  var result=JsAnalysis.analyze(inline,"https://lab.test/assets/app.js");ok("inline source map decodes and recovers exact source",result.miner().recovered().size()==1&&result.miner().recovered().get(0).content().contains("/api/recovered"));ok("recovered original automatically adds API and method",result.endpoints().stream().anyMatch(e->e.url().equals("https://lab.test/api/recovered")&&e.method().equals("POST")&&e.start()==-1));
  ok("recovered result totals reflect merged API rows",result.status().contains("URL/API 2"));
  var merged=JsMiner.mergeRecon(JsMiner.analyze("", "https://lab.test/a.js"),JsMiner.analyze("require('recovered-package'); fetch('https://recovered.s3.amazonaws.com/api');", "https://lab.test/a.js"));ok("recovered source domain cloud and dependency findings merge",merged.clouds().size()==1&&merged.dependencies().size()==1&&merged.domains().stream().anyMatch(d->d.host().equals("recovered.s3.amazonaws.com")));
  var indexed=JsMiner.sourceMap("{\"version\":3,\"sections\":[{\"offset\":{\"line\":0,\"column\":0},\"map\":"+map+"}]}","https://lab.test/app.map");ok("indexed map embedded sections recovered",indexed.size()==1);
  ok("source map without embedded contents does not invent original",JsMiner.sourceMap("{\"version\":3,\"sources\":[\"a.js\"]}","https://lab.test/a.map").isEmpty());
  bad("malformed source map rejected",()->JsMiner.sourceMap("{\"version\":3,\"sources\":[","x"));bad("unsupported map version rejected",()->JsMiner.sourceMap("{\"version\":2,\"sources\":[]}","x"));bad("duplicate JSON keys rejected",()->MinerJson.parse("{\"a\":1,\"a\":2}"));
  var refs=JsMiner.analyze("//# sourceMappingURL=app.js.map\n//# sourceMappingURL=https://outside.test/a.map","https://lab.test/assets/app.js");var candidates=JsMiner.mapCandidates("https://lab.test/assets/app.js?token=secret",refs.maps());ok("same origin reference and bounded guesses",candidates.equals(List.of("https://lab.test/assets/app.js.map","https://lab.test/assets/app.map")));ok("external map not requested",candidates.stream().noneMatch(v->v.contains("outside.test")));ok("different port map excluded",JsMiner.mapCandidates("http://lab.test:8080/a.js",List.of(new JsMiner.MapRef("http://lab.test:8081/a.map",""))).stream().noneMatch(v->v.contains(":8081")));
  var non64=JsMiner.analyze("//# sourceMappingURL=data:application/json,"+java.net.URLEncoder.encode(map,StandardCharsets.UTF_8).replace("+","%20"),"https://lab.test/a.js");ok("percent encoded inline map decoded",non64.recovered().size()==1);
  String[] urls={"https://x.s3.amazonaws.com/a","https://x.blob.core.windows.net/a","https://storage.googleapis.com/a","https://x.cloudfront.net/a","https://x.digitaloceanspaces.com/a","https://x.oraclecloud.com/a","https://x.aliyuncs.com/a","https://x.firebaseio.com/a","https://x.rackcdn.com/a","https://x.dream.io/a"};var cloud=JsMiner.analyze(String.join("\n",urls)+"?token=hidden\nhttps://api.lab.test/v1\nhttps://s3.amazonaws.com.evil.test/a","https://lab.test/app.js");ok("all ten cloud provider families classified",cloud.clouds().size()==10);ok("cloud hostname suffix spoof excluded",cloud.clouds().stream().noneMatch(c->c.url().contains("evil.test")));ok("cloud query strings masked",cloud.clouds().stream().noneMatch(c->c.url().contains("token=")));ok("source subdomain relation explicit",cloud.domains().stream().anyMatch(d->d.host().equals("api.lab.test")&&d.relation().equals("출처의 하위 도메인")));
  var dep=JsMiner.analyze("import a from 'axios'; const p=require('@team/private/subpath'); require('./local');require('node:fs'); require('fs'); import('lazy-package');","https://lab.test/a.js");ok("imports requires dynamic literals and scopes normalized",dep.dependencies().size()==3&&dep.dependencies().stream().anyMatch(d->d.name().equals("@team/private")&&d.scope().equals("team")));var manifest=JsMiner.analyze("{\"dependencies\":{\"axios\":\"1\"},\"devDependencies\":{\"@team/private\":\"1\"}}","https://lab.test/package.json");ok("package JSON dependencies and development dependencies",manifest.dependencies().size()==2);
  var d=dep.dependencies().get(0);ok("registry 200 registered",JsMiner.checkDependency(d,"https://registry.test",u->new JsMiner.Reply(200,"{\"name\":\""+d.name()+"\"}")).status().equals("등록됨"));ok("registry soft-404 HTML 200 remains inconclusive",JsMiner.checkDependency(d,"https://registry.test",u->new JsMiner.Reply(200,"<html>login</html>")).status().contains("미판정"));ok("registry 404 remains candidate not confirmed confusion",JsMiner.checkDependency(d,"https://registry.test",u->new JsMiner.Reply(404,"{}")).status().contains("확정 아님"));ok("registry 429 inconclusive",JsMiner.checkDependency(d,"https://registry.test",u->new JsMiner.Reply(429,"{}")).status().contains("조회 제한"));ok("registry redirect inconclusive",JsMiner.checkDependency(d,"https://registry.test",u->new JsMiner.Reply(302,"{}")).status().contains("리다이렉트"));ok("registry error inconclusive",JsMiner.checkDependency(d,"https://registry.test",u->{throw new java.io.IOException();}).status().contains("조회 오류"));
  Path temp=Files.createTempDirectory("miner-test-");try{Path dumped=JsMiner.dump(temp,Map.of("https://lab.test/a.js?secret=hidden","captured JS"),indexed);ok("dump manifest and raw captured contents",Files.exists(dumped.resolve("manifest.tsv"))&&Files.readString(dumped.resolve("001-captured.txt")).equals("captured JS"));ok("map traversal name cannot escape output directory",Files.exists(dumped.resolve("002-source-escape.js"))&&!Files.exists(temp.resolve("escape.js")));ok("dump manifest source queries omitted",!Files.readString(dumped.resolve("manifest.tsv")).contains("hidden"));}finally{try(var walk=Files.walk(temp)){for(Path p:walk.sorted(Comparator.reverseOrder()).toList())Files.delete(p);}}
  ok("Shannon entropy shown with masked secret",JsAnalysis.analyze("const apiKey='AIza"+"Z".repeat(35)+"';","https://lab.test/a.js").secrets().stream().allMatch(s->s.masked().contains("가림")&&s.confidence().contains("Shannon")));
  System.out.println("JsMinerTest: "+count+" checks passed");
 }
}
